window.PYTHON_FILES = {
  "__init__.py": "\"\"\"\nConnect Four AI Engine - Package Initialization\n\"\"\"\nfrom python.board import Board, ROWS, COLS, EMPTY, PLAYER, AI\nfrom python.game_logic import ConnectFourGame\nfrom python.evaluation import score_position\nfrom python.minimax import minimax_search\nfrom python.alpha_beta import alpha_beta_search\nfrom python.ai_engine import AIEngine\n\n__all__ = [\n    \"Board\",\n    \"ROWS\",\n    \"COLS\",\n    \"EMPTY\",\n    \"PLAYER\",\n    \"AI\",\n    \"ConnectFourGame\",\n    \"score_position\",\n    \"minimax_search\",\n    \"alpha_beta_search\",\n    \"AIEngine\",\n]\n",
  "board.py": "\"\"\"\nConnect Four Board representation and primitive operations.\nGrid: 6 rows (0 is top, 5 is bottom) x 7 columns (0 to 6).\n\"\"\"\nfrom typing import List, Tuple, Optional\n\nROWS = 6\nCOLS = 7\nEMPTY = 0\nPLAYER = 1  # Human (Red)\nAI = 2      # Computer (Yellow)\n\n# Strategic column ordering: Center column first maximizes alpha-beta pruning\nCOLUMN_ORDER = [3, 2, 4, 1, 5, 0, 6]\n\n\nclass Board:\n    def __init__(self, grid: Optional[List[List[int]]] = None):\n        if grid is not None:\n            self.grid = [row[:] for row in grid]\n        else:\n            self.grid = [[EMPTY for _ in range(COLS)] for _ in range(ROWS)]\n\n    def copy(self) -> 'Board':\n        return Board(self.grid)\n\n    def is_valid_location(self, col: int) -> bool:\n        if 0 <= col < COLS:\n            return self.grid[0][col] == EMPTY\n        return False\n\n    def get_valid_locations(self) -> List[int]:\n        \"\"\"Returns valid columns ordered for search efficiency (center outwards).\"\"\"\n        valid = []\n        for col in COLUMN_ORDER:\n            if self.is_valid_location(col):\n                valid.append(col)\n        return valid\n\n    def get_next_open_row(self, col: int) -> Optional[int]:\n        \"\"\"Scans from bottom row (ROWS - 1) up to row 0 for first EMPTY cell.\"\"\"\n        for r in range(ROWS - 1, -1, -1):\n            if self.grid[r][col] == EMPTY:\n                return r\n        return None\n\n    def drop_piece(self, row: int, col: int, piece: int) -> None:\n        self.grid[row][col] = piece\n\n    def make_move(self, col: int, piece: int) -> Optional[int]:\n        \"\"\"Helper to drop a piece into a column. Returns the row where it landed, or None if invalid.\"\"\"\n        if not self.is_valid_location(col):\n            return None\n        row = self.get_next_open_row(col)\n        if row is not None:\n            self.drop_piece(row, col, piece)\n            return row\n        return None\n\n    def winning_move(self, piece: int) -> bool:\n        \"\"\"Check whether `piece` has 4 in a row in any direction.\"\"\"\n        # 1. Horizontal\n        for r in range(ROWS):\n            for c in range(COLS - 3):\n                if (self.grid[r][c] == piece and\n                    self.grid[r][c + 1] == piece and\n                    self.grid[r][c + 2] == piece and\n                    self.grid[r][c + 3] == piece):\n                    return True\n\n        # 2. Vertical\n        for c in range(COLS):\n            for r in range(ROWS - 3):\n                if (self.grid[r][c] == piece and\n                    self.grid[r + 1][c] == piece and\n                    self.grid[r + 2][c] == piece and\n                    self.grid[r + 3][c] == piece):\n                    return True\n\n        # 3. Positively sloped diagonals (/)\n        for r in range(3, ROWS):\n            for c in range(COLS - 3):\n                if (self.grid[r][c] == piece and\n                    self.grid[r - 1][c + 1] == piece and\n                    self.grid[r - 2][c + 2] == piece and\n                    self.grid[r - 3][c + 3] == piece):\n                    return True\n\n        # 4. Negatively sloped diagonals (\\)\n        for r in range(ROWS - 3):\n            for c in range(COLS - 3):\n                if (self.grid[r][c] == piece and\n                    self.grid[r + 1][c + 1] == piece and\n                    self.grid[r + 2][c + 2] == piece and\n                    self.grid[r + 3][c + 3] == piece):\n                    return True\n\n        return False\n\n    def get_winning_coordinates(self, piece: int) -> Optional[List[Tuple[int, int]]]:\n        \"\"\"Returns list of four (row, col) coordinates forming a win, or None.\"\"\"\n        # 1. Horizontal\n        for r in range(ROWS):\n            for c in range(COLS - 3):\n                if all(self.grid[r][c + i] == piece for i in range(4)):\n                    return [(r, c + i) for i in range(4)]\n\n        # 2. Vertical\n        for c in range(COLS):\n            for r in range(ROWS - 3):\n                if all(self.grid[r + i][c] == piece for i in range(4)):\n                    return [(r + i, c) for i in range(4)]\n\n        # 3. Positively sloped diagonals (/)\n        for r in range(3, ROWS):\n            for c in range(COLS - 3):\n                if all(self.grid[r - i][c + i] == piece for i in range(4)):\n                    return [(r - i, c + i) for i in range(4)]\n\n        # 4. Negatively sloped diagonals (\\)\n        for r in range(ROWS - 3):\n            for c in range(COLS - 3):\n                if all(self.grid[r + i][c + i] == piece for i in range(4)):\n                    return [(r + i, c + i) for i in range(4)]\n\n        return None\n\n    def is_full(self) -> bool:\n        return all(self.grid[0][c] != EMPTY for c in range(COLS))\n\n    def is_terminal_node(self) -> bool:\n        return self.winning_move(PLAYER) or self.winning_move(AI) or self.is_full()\n\n    def to_list(self) -> List[List[int]]:\n        return [row[:] for row in self.grid]\n\n    def __str__(self) -> str:\n        symbols = {EMPTY: '.', PLAYER: 'X', AI: 'O'}\n        lines = [' '.join(str(c) for c in range(COLS))]\n        lines.append('-' * (COLS * 2 - 1))\n        for row in self.grid:\n            lines.append(' '.join(symbols[cell] for cell in row))\n        return '\\n'.join(lines)\n",
  "evaluation.py": "\"\"\"\nHeuristic Evaluation Function for Connect Four.\nEvaluates the board state from the perspective of a given piece (usually AI).\nConsiders center column control, horizontal, vertical, and diagonal windows of 4.\n\"\"\"\nfrom typing import List\nfrom python.board import ROWS, COLS, EMPTY, PLAYER, AI, Board\n\nWINDOW_LENGTH = 4\n\n\ndef evaluate_window(window: List[int], piece: int) -> int:\n    \"\"\"Scores a single 4-cell window from the perspective of `piece`.\"\"\"\n    score = 0\n    opp_piece = PLAYER if piece == AI else AI\n\n    count_piece = window.count(piece)\n    count_empty = window.count(EMPTY)\n    count_opp = window.count(opp_piece)\n\n    if count_piece == 4:\n        score += 100000\n    elif count_piece == 3 and count_empty == 1:\n        score += 100\n    elif count_piece == 2 and count_empty == 2:\n        score += 10\n\n    # Blocking opponent threats: Penalize strongly if opponent is set to win on next move\n    if count_opp == 3 and count_empty == 1:\n        score -= 120\n    elif count_opp == 2 and count_empty == 2:\n        score -= 10\n\n    return score\n\n\ndef score_position(board: Board, piece: int) -> int:\n    \"\"\"Evaluates the entire board state from the perspective of `piece`.\"\"\"\n    score = 0\n\n    # 1. Center column control (strategic advantage in Connect 4)\n    center_col = [board.grid[r][COLS // 2] for r in range(ROWS)]\n    center_count = center_col.count(piece)\n    score += center_count * 6\n\n    # Inner columns (2 and 4) slight preference\n    col2 = [board.grid[r][2] for r in range(ROWS)]\n    col4 = [board.grid[r][4] for r in range(ROWS)]\n    score += col2.count(piece) * 2 + col4.count(piece) * 2\n\n    # 2. Horizontal evaluation\n    for r in range(ROWS):\n        row_array = board.grid[r]\n        for c in range(COLS - 3):\n            window = row_array[c:c + WINDOW_LENGTH]\n            score += evaluate_window(window, piece)\n\n    # 3. Vertical evaluation\n    for c in range(COLS):\n        col_array = [board.grid[r][c] for r in range(ROWS)]\n        for r in range(ROWS - 3):\n            window = col_array[r:r + WINDOW_LENGTH]\n            score += evaluate_window(window, piece)\n\n    # 4. Positively sloped diagonals (/)\n    for r in range(3, ROWS):\n        for c in range(COLS - 3):\n            window = [board.grid[r - i][c + i] for i in range(WINDOW_LENGTH)]\n            score += evaluate_window(window, piece)\n\n    # 5. Negatively sloped diagonals (\\)\n    for r in range(ROWS - 3):\n        for c in range(COLS - 3):\n            window = [board.grid[r + i][c + i] for i in range(WINDOW_LENGTH)]\n            score += evaluate_window(window, piece)\n\n    return score\n",
  "game_logic.py": "\"\"\"\nHigh-level Connect Four Game State Manager.\nHandles turns, move history, validation, and terminal condition checking.\n\"\"\"\nfrom typing import List, Dict, Any, Optional\nfrom python.board import Board, ROWS, COLS, EMPTY, PLAYER, AI\n\n\nclass ConnectFourGame:\n    def __init__(self):\n        self.board = Board()\n        self.current_turn = PLAYER  # Human plays first by default\n        self.move_history: List[Dict[str, Any]] = []\n        self.winner: Optional[int] = None\n        self.winning_coords: Optional[List[tuple]] = None\n        self.is_over: bool = False\n\n    def reset(self, first_turn: int = PLAYER) -> None:\n        self.board = Board()\n        self.current_turn = first_turn\n        self.move_history = []\n        self.winner = None\n        self.winning_coords = None\n        self.is_over = False\n\n    def make_move(self, col: int) -> Dict[str, Any]:\n        \"\"\"Applies a move for the current player in column `col`. Returns move details.\"\"\"\n        if self.is_over:\n            return {\"success\": False, \"error\": \"Game is already over\"}\n\n        if not self.board.is_valid_location(col):\n            return {\"success\": False, \"error\": f\"Column {col} is full or invalid\"}\n\n        row = self.board.make_move(col, self.current_turn)\n        move_info = {\n            \"move_number\": len(self.move_history) + 1,\n            \"player\": self.current_turn,\n            \"column\": col,\n            \"row\": row,\n        }\n        self.move_history.append(move_info)\n\n        # Check win condition\n        if self.board.winning_move(self.current_turn):\n            self.winner = self.current_turn\n            self.winning_coords = self.board.get_winning_coordinates(self.current_turn)\n            self.is_over = True\n            return {\n                \"success\": True,\n                \"move\": move_info,\n                \"status\": \"win\",\n                \"winner\": self.winner,\n                \"winning_coords\": self.winning_coords,\n            }\n\n        # Check draw condition\n        if self.board.is_full():\n            self.winner = None\n            self.is_over = True\n            return {\n                \"success\": True,\n                \"move\": move_info,\n                \"status\": \"draw\",\n                \"winner\": None,\n                \"winning_coords\": None,\n            }\n\n        # Switch turn\n        self.current_turn = AI if self.current_turn == PLAYER else PLAYER\n        return {\n            \"success\": True,\n            \"move\": move_info,\n            \"status\": \"in_progress\",\n            \"next_turn\": self.current_turn,\n        }\n\n    def undo_move(self) -> Optional[Dict[str, Any]]:\n        \"\"\"Undo last single move.\"\"\"\n        if not self.move_history:\n            return None\n\n        last_move = self.move_history.pop()\n        r = last_move[\"row\"]\n        c = last_move[\"column\"]\n        self.board.grid[r][c] = EMPTY\n        self.current_turn = last_move[\"player\"]\n        self.winner = None\n        self.winning_coords = None\n        self.is_over = False\n        return last_move\n\n    def get_state(self) -> Dict[str, Any]:\n        return {\n            \"grid\": self.board.to_list(),\n            \"current_turn\": self.current_turn,\n            \"is_over\": self.is_over,\n            \"winner\": self.winner,\n            \"winning_coords\": self.winning_coords,\n            \"history\": self.move_history,\n            \"valid_columns\": [c for c in range(COLS) if self.board.is_valid_location(c)],\n        }\n",
  "minimax.py": "\"\"\"\nMinimax Algorithm Implementation for Connect Four.\nPerforms an exhaustive depth-limited search across the game tree.\nMaximizing player is AI (piece=AI), Minimizing player is Human (piece=PLAYER).\n\"\"\"\nimport math\nfrom typing import Tuple, Optional, Dict, Any, List\nfrom python.board import Board, ROWS, COLS, EMPTY, PLAYER, AI\nfrom python.evaluation import score_position\n\nWIN_SCORE = 10000000\n\n\ndef minimax_search(\n    board: Board,\n    depth: int,\n    maximizing_player: bool,\n    stats: Optional[Dict[str, Any]] = None,\n    collect_trace: bool = False,\n    node_id_counter: Optional[List[int]] = None,\n    parent_id: Optional[int] = None,\n    move_col: Optional[int] = None,\n) -> Tuple[Optional[int], float, Optional[Dict[str, Any]]]:\n    \"\"\"\n    Minimax search with visited node counting and optional tree trace collection.\n    Returns: (best_column, best_score, trace_dict)\n    \"\"\"\n    if stats is None:\n        stats = {\"nodes_visited\": 0, \"pruned_nodes\": 0}\n    stats[\"nodes_visited\"] += 1\n\n    current_node_id = None\n    node_trace = None\n    if collect_trace:\n        if node_id_counter is None:\n            node_id_counter = [0]\n        current_node_id = node_id_counter[0]\n        node_id_counter[0] += 1\n        node_trace = {\n            \"id\": current_node_id,\n            \"parent_id\": parent_id,\n            \"depth\": depth,\n            \"move\": move_col,\n            \"is_max\": maximizing_player,\n            \"score\": None,\n            \"children\": [],\n            \"is_best\": False,\n            \"pruned\": False,\n        }\n\n    valid_locations = board.get_valid_locations()\n    is_terminal = board.is_terminal_node()\n\n    # Terminal or depth limit reached\n    if depth == 0 or is_terminal:\n        if is_terminal:\n            if board.winning_move(AI):\n                score = WIN_SCORE + depth  # Prefer faster win\n            elif board.winning_move(PLAYER):\n                score = -WIN_SCORE - depth  # Prefer delayed loss\n            else:\n                score = 0  # Draw\n        else:\n            score = score_position(board, AI)\n\n        if node_trace:\n            node_trace[\"score\"] = score\n        return None, score, node_trace\n\n    if maximizing_player:\n        max_eval = -math.inf\n        best_col = valid_locations[0] if valid_locations else None\n\n        for col in valid_locations:\n            row = board.get_next_open_row(col)\n            board.drop_piece(row, col, AI)\n\n            _, eval_score, child_trace = minimax_search(\n                board,\n                depth - 1,\n                False,\n                stats,\n                collect_trace,\n                node_id_counter,\n                current_node_id,\n                col,\n            )\n\n            board.drop_piece(row, col, EMPTY)\n\n            if node_trace and child_trace:\n                node_trace[\"children\"].append(child_trace)\n\n            if eval_score > max_eval:\n                max_eval = eval_score\n                best_col = col\n\n        if node_trace:\n            node_trace[\"score\"] = max_eval\n            # Mark optimal child\n            for child in node_trace[\"children\"]:\n                if child.get(\"move\") == best_col and child.get(\"score\") == max_eval:\n                    child[\"is_best\"] = True\n\n        return best_col, max_eval, node_trace\n\n    else:  # Minimizing player\n        min_eval = math.inf\n        best_col = valid_locations[0] if valid_locations else None\n\n        for col in valid_locations:\n            row = board.get_next_open_row(col)\n            board.drop_piece(row, col, PLAYER)\n\n            _, eval_score, child_trace = minimax_search(\n                board,\n                depth - 1,\n                True,\n                stats,\n                collect_trace,\n                node_id_counter,\n                current_node_id,\n                col,\n            )\n\n            board.drop_piece(row, col, EMPTY)\n\n            if node_trace and child_trace:\n                node_trace[\"children\"].append(child_trace)\n\n            if eval_score < min_eval:\n                min_eval = eval_score\n                best_col = col\n\n        if node_trace:\n            node_trace[\"score\"] = min_eval\n            # Mark optimal child\n            for child in node_trace[\"children\"]:\n                if child.get(\"move\") == best_col and child.get(\"score\") == min_eval:\n                    child[\"is_best\"] = True\n\n        return best_col, min_eval, node_trace\n",
  "alpha_beta.py": "\"\"\"\nAlpha-Beta Pruning Algorithm Implementation for Connect Four.\nOptimizes Minimax by cutting off branches that cannot influence the final decision.\nMaintains alpha (best score for MAX) and beta (best score for MIN).\n\"\"\"\nimport math\nfrom typing import Tuple, Optional, Dict, Any, List\nfrom python.board import Board, ROWS, COLS, EMPTY, PLAYER, AI\nfrom python.evaluation import score_position\n\nWIN_SCORE = 10000000\n\n\ndef alpha_beta_search(\n    board: Board,\n    depth: int,\n    alpha: float = -math.inf,\n    beta: float = math.inf,\n    maximizing_player: bool = True,\n    stats: Optional[Dict[str, Any]] = None,\n    collect_trace: bool = False,\n    node_id_counter: Optional[List[int]] = None,\n    parent_id: Optional[int] = None,\n    move_col: Optional[int] = None,\n) -> Tuple[Optional[int], float, Optional[Dict[str, Any]]]:\n    \"\"\"\n    Alpha-Beta Pruning search with visited and pruned node counting.\n    Returns: (best_column, best_score, trace_dict)\n    \"\"\"\n    if stats is None:\n        stats = {\n            \"nodes_visited\": 0,\n            \"pruned_nodes\": 0,\n            \"prune_events\": 0,\n        }\n    stats[\"nodes_visited\"] += 1\n\n    current_node_id = None\n    node_trace = None\n    if collect_trace:\n        if node_id_counter is None:\n            node_id_counter = [0]\n        current_node_id = node_id_counter[0]\n        node_id_counter[0] += 1\n        node_trace = {\n            \"id\": current_node_id,\n            \"parent_id\": parent_id,\n            \"depth\": depth,\n            \"move\": move_col,\n            \"is_max\": maximizing_player,\n            \"alpha_in\": alpha,\n            \"beta_in\": beta,\n            \"alpha_out\": alpha,\n            \"beta_out\": beta,\n            \"score\": None,\n            \"children\": [],\n            \"pruned_branches\": [],\n            \"is_best\": False,\n            \"pruned\": False,\n        }\n\n    valid_locations = board.get_valid_locations()\n    is_terminal = board.is_terminal_node()\n\n    if depth == 0 or is_terminal:\n        if is_terminal:\n            if board.winning_move(AI):\n                score = WIN_SCORE + depth\n            elif board.winning_move(PLAYER):\n                score = -WIN_SCORE - depth\n            else:\n                score = 0\n        else:\n            score = score_position(board, AI)\n\n        if node_trace:\n            node_trace[\"score\"] = score\n            node_trace[\"alpha_out\"] = alpha\n            node_trace[\"beta_out\"] = beta\n        return None, score, node_trace\n\n    if maximizing_player:\n        max_eval = -math.inf\n        best_col = valid_locations[0] if valid_locations else None\n\n        for idx, col in enumerate(valid_locations):\n            row = board.get_next_open_row(col)\n            board.drop_piece(row, col, AI)\n\n            _, eval_score, child_trace = alpha_beta_search(\n                board,\n                depth - 1,\n                alpha,\n                beta,\n                False,\n                stats,\n                collect_trace,\n                node_id_counter,\n                current_node_id,\n                col,\n            )\n\n            board.drop_piece(row, col, EMPTY)\n\n            if node_trace and child_trace:\n                node_trace[\"children\"].append(child_trace)\n\n            if eval_score > max_eval:\n                max_eval = eval_score\n                best_col = col\n\n            alpha = max(alpha, eval_score)\n\n            if beta <= alpha:\n                # Alpha-Beta Pruning Cut-off\n                remaining = len(valid_locations) - (idx + 1)\n                stats[\"pruned_nodes\"] += remaining\n                stats[\"prune_events\"] += 1\n\n                if node_trace:\n                    # Record pruned branches for educational visualization\n                    for pruned_col in valid_locations[idx + 1:]:\n                        node_trace[\"pruned_branches\"].append({\n                            \"move\": pruned_col,\n                            \"reason\": f\"\u03b2 ({beta}) \u2264 \u03b1 ({alpha})\",\n                        })\n                break\n\n        if node_trace:\n            node_trace[\"score\"] = max_eval\n            node_trace[\"alpha_out\"] = alpha\n            node_trace[\"beta_out\"] = beta\n            for child in node_trace[\"children\"]:\n                if child.get(\"move\") == best_col and child.get(\"score\") == max_eval:\n                    child[\"is_best\"] = True\n\n        return best_col, max_eval, node_trace\n\n    else:  # Minimizing player\n        min_eval = math.inf\n        best_col = valid_locations[0] if valid_locations else None\n\n        for idx, col in enumerate(valid_locations):\n            row = board.get_next_open_row(col)\n            board.drop_piece(row, col, PLAYER)\n\n            _, eval_score, child_trace = alpha_beta_search(\n                board,\n                depth - 1,\n                alpha,\n                beta,\n                True,\n                stats,\n                collect_trace,\n                node_id_counter,\n                current_node_id,\n                col,\n            )\n\n            board.drop_piece(row, col, EMPTY)\n\n            if node_trace and child_trace:\n                node_trace[\"children\"].append(child_trace)\n\n            if eval_score < min_eval:\n                min_eval = eval_score\n                best_col = col\n\n            beta = min(beta, eval_score)\n\n            if beta <= alpha:\n                # Alpha-Beta Pruning Cut-off\n                remaining = len(valid_locations) - (idx + 1)\n                stats[\"pruned_nodes\"] += remaining\n                stats[\"prune_events\"] += 1\n\n                if node_trace:\n                    for pruned_col in valid_locations[idx + 1:]:\n                        node_trace[\"pruned_branches\"].append({\n                            \"move\": pruned_col,\n                            \"reason\": f\"\u03b2 ({beta}) \u2264 \u03b1 ({alpha})\",\n                        })\n                break\n\n        if node_trace:\n            node_trace[\"score\"] = min_eval\n            node_trace[\"alpha_out\"] = alpha\n            node_trace[\"beta_out\"] = beta\n            for child in node_trace[\"children\"]:\n                if child.get(\"move\") == best_col and child.get(\"score\") == min_eval:\n                    child[\"is_best\"] = True\n\n        return best_col, min_eval, node_trace\n",
  "ai_engine.py": "\"\"\"\nConnect Four AI Engine - High-level API.\nExposes clean functions used by Pyodide / Web Workers / CLI:\n- get_best_move\n- get_hint\n- run_benchmark\n- get_tree_trace\n\"\"\"\nimport time\nimport json\nfrom typing import Dict, Any, List, Optional\nfrom python.board import Board, ROWS, COLS, EMPTY, PLAYER, AI\nfrom python.minimax import minimax_search\nfrom python.alpha_beta import alpha_beta_search\nfrom python.evaluation import score_position\n\n# Preset depths corresponding to prompt requirements\nDIFFICULTY_DEPTHS = {\n    \"easy\": 1,\n    \"medium\": 3,\n    \"hard\": 5,\n}\n\n\nclass AIEngine:\n    @staticmethod\n    def get_best_move(\n        grid: List[List[int]],\n        algorithm: str = \"alpha_beta\",\n        depth: int = 4,\n        player: int = AI,\n        collect_trace: bool = False,\n    ) -> Dict[str, Any]:\n        \"\"\"\n        Executes chosen search algorithm on board grid.\n        Returns execution metrics, selected move, and evaluation score.\n        \"\"\"\n        board = Board(grid)\n        stats = {\n            \"nodes_visited\": 0,\n            \"pruned_nodes\": 0,\n            \"prune_events\": 0,\n        }\n\n        # Validate that game is not already in terminal state\n        if board.is_terminal_node():\n            return {\n                \"success\": False,\n                \"error\": \"Game is already in a terminal state\",\n            }\n\n        start_time = time.perf_counter()\n\n        algo_normalized = algorithm.lower().replace(\"-\", \"_\").replace(\" \", \"_\")\n        trace = None\n\n        if \"minimax\" in algo_normalized and \"alpha\" not in algo_normalized:\n            algo_name = \"Minimax\"\n            best_col, score, trace = minimax_search(\n                board,\n                depth,\n                maximizing_player=(player == AI),\n                stats=stats,\n                collect_trace=collect_trace,\n            )\n        else:\n            algo_name = \"Alpha-Beta Pruning\"\n            best_col, score, trace = alpha_beta_search(\n                board,\n                depth,\n                maximizing_player=(player == AI),\n                stats=stats,\n                collect_trace=collect_trace,\n            )\n\n        exec_time_ms = round((time.perf_counter() - start_time) * 1000, 2)\n\n        # Fallback if no valid col found (e.g. board full)\n        if best_col is None:\n            valid = board.get_valid_locations()\n            best_col = valid[0] if valid else None\n\n        result = {\n            \"success\": True,\n            \"selected_column\": best_col,\n            \"evaluation_score\": int(score) if abs(score) < 100000000 else int(score),\n            \"nodes_visited\": stats[\"nodes_visited\"],\n            \"pruned_nodes\": stats[\"pruned_nodes\"],\n            \"prune_events\": stats[\"prune_events\"],\n            \"search_depth\": depth,\n            \"execution_time_ms\": exec_time_ms,\n            \"algorithm_name\": algo_name,\n        }\n\n        if collect_trace and trace:\n            result[\"search_trace\"] = trace\n\n        return result\n\n    @staticmethod\n    def get_hint(grid: List[List[int]], algorithm: str = \"alpha_beta\", depth: int = 3) -> Dict[str, Any]:\n        \"\"\"\n        Returns recommended move for the Human player (PLAYER = 1).\n        \"\"\"\n        # Evaluates from Human perspective\n        return AIEngine.get_best_move(\n            grid=grid,\n            algorithm=algorithm,\n            depth=depth,\n            player=PLAYER,\n            collect_trace=False,\n        )\n\n    @staticmethod\n    def run_benchmark(grid: List[List[int]], depth: int = 4) -> Dict[str, Any]:\n        \"\"\"\n        Runs both Minimax and Alpha-Beta on the exact same board state,\n        depth, and evaluation function to provide a 100% fair scientific comparison.\n        \"\"\"\n        board_minimax = Board(grid)\n        board_alphabeta = Board(grid)\n\n        # 1. Run Minimax\n        stats_mm = {\"nodes_visited\": 0, \"pruned_nodes\": 0}\n        t0 = time.perf_counter()\n        best_col_mm, score_mm, _ = minimax_search(\n            board_minimax,\n            depth=depth,\n            maximizing_player=True,\n            stats=stats_mm,\n            collect_trace=False,\n        )\n        t_mm = round((time.perf_counter() - t0) * 1000, 2)\n\n        # 2. Run Alpha-Beta\n        stats_ab = {\"nodes_visited\": 0, \"pruned_nodes\": 0, \"prune_events\": 0}\n        t1 = time.perf_counter()\n        best_col_ab, score_ab, _ = alpha_beta_search(\n            board_alphabeta,\n            depth=depth,\n            maximizing_player=True,\n            stats=stats_ab,\n            collect_trace=False,\n        )\n        t_ab = round((time.perf_counter() - t1) * 1000, 2)\n\n        # Pruning efficiency calculation\n        nodes_mm = stats_mm[\"nodes_visited\"]\n        nodes_ab = stats_ab[\"nodes_visited\"]\n        reduction_pct = round(((nodes_mm - nodes_ab) / max(nodes_mm, 1)) * 100, 1) if nodes_mm > 0 else 0.0\n        speedup = round(t_mm / max(t_ab, 0.001), 2) if t_ab > 0 else 1.0\n\n        return {\n            \"depth\": depth,\n            \"minimax\": {\n                \"algorithm\": \"Minimax\",\n                \"best_move\": best_col_mm,\n                \"score\": int(score_mm),\n                \"nodes_visited\": nodes_mm,\n                \"pruned_nodes\": 0,\n                \"execution_time_ms\": t_mm,\n            },\n            \"alpha_beta\": {\n                \"algorithm\": \"Alpha-Beta Pruning\",\n                \"best_move\": best_col_ab,\n                \"score\": int(score_ab),\n                \"nodes_visited\": nodes_ab,\n                \"pruned_nodes\": stats_ab[\"pruned_nodes\"],\n                \"prune_events\": stats_ab[\"prune_events\"],\n                \"execution_time_ms\": t_ab,\n            },\n            \"comparison\": {\n                \"equivalent_decision\": (best_col_mm == best_col_ab),\n                \"equivalent_score\": (score_mm == score_ab),\n                \"nodes_saved\": nodes_mm - nodes_ab,\n                \"reduction_percentage\": reduction_pct,\n                \"speedup_factor\": speedup,\n            },\n        }\n\n    @staticmethod\n    def get_tree_trace(grid: List[List[int]], algorithm: str = \"alpha_beta\", depth: int = 2) -> Dict[str, Any]:\n        \"\"\"\n        Generates structured tree trace specifically for the AI Lab interactive visualization.\n        Depth defaults to 2 (or 3) to keep the educational tree readable.\n        \"\"\"\n        # Cap visualizer depth to 3 for performance and rendering clarity\n        safe_depth = min(depth, 3)\n        return AIEngine.get_best_move(\n            grid=grid,\n            algorithm=algorithm,\n            depth=safe_depth,\n            player=AI,\n            collect_trace=True,\n        )\n\n\n# Global helper functions for easy JS / Pyodide invocation\ndef py_get_best_move(grid_json: str, algorithm: str, depth: int) -> str:\n    grid = json.loads(grid_json)\n    result = AIEngine.get_best_move(grid, algorithm=algorithm, depth=depth)\n    return json.dumps(result)\n\n\ndef py_get_hint(grid_json: str, algorithm: str, depth: int) -> str:\n    grid = json.loads(grid_json)\n    result = AIEngine.get_hint(grid, algorithm=algorithm, depth=depth)\n    return json.dumps(result)\n\n\ndef py_run_benchmark(grid_json: str, depth: int) -> str:\n    grid = json.loads(grid_json)\n    result = AIEngine.run_benchmark(grid, depth=depth)\n    return json.dumps(result)\n\n\ndef py_get_tree_trace(grid_json: str, algorithm: str, depth: int) -> str:\n    grid = json.loads(grid_json)\n    result = AIEngine.get_tree_trace(grid, algorithm=algorithm, depth=depth)\n    return json.dumps(result)\n"
};
